    bucket = {}
    for pr, ref_score in _iter_trials(preds, condition, injection, run, refs, reference):
        b = bucket.setdefault(pr["pid"], {"n": 0, "n_big": 0, "n_fail": 0})
        if pr["status"] in FAIL_STATUSES or pr["score"] is None:
